        $r = $this->http->request('POST', '/v1/billing/subscriptions/' . rawurlencode($id) . '/extend_trial', body: $body, idempotencyKey: $idempotencyKey);

        return is_array($r) ? $r : [];
    }

    /**
     * Re-read one subscription from Stripe now, with your own key, and apply what Stripe reports (status, plan, period, cancellation). For an instance that syncs without a Stripe webhook, or to refresh one subscription on demand. A subscription on another account, or not Stripe, is refused.
     *
     * `POST /v1/billing/subscriptions/{id}/sync` (scope `billing:write`)
     *
     * @param string $id the `id` path segment
     * @param string|null $idempotencyKey sent as `Idempotency-Key`; a retry with the same key replays the first response
     * @return array{object:mixed, id:string, subject_type:'user'|'org', subject_id:string, plan_id:string, status:string, stripe_subscription_id:string|null, stripe_customer_id:string|null, current_period_end:int|null, provider?:string, cancel_at_period_end?:bool, entitlements?:array{features?:list<string>, limits?:array<string,int|float>}|null, subscriptions?:list<array<string,mixed>>, created_at:int, updated_at:int}
     */
    public function syncSubscriptions(string $id, ?string $idempotencyKey = null): array
    {
        $r = $this->http->request('POST', '/v1/billing/subscriptions/' . rawurlencode($id) . '/sync', idempotencyKey: $idempotencyKey);

        return is_array($r) ? $r : [];
    }

    /**
     * Read back the usage Atlas recorded for a subject: the total and the total per feature over a time range, and with `events=true` the individual events (keyset-paged). `period=current` counts from the start of the subject's current billing period. Usage that only your payment provider holds is not here; ask the provider with POST /v1/billing/check.
     *
     * `GET /v1/billing/usage` (scope `billing:read`)
     *
     * @param array{subject_type?:'user'|'org', subject_id?:string, feature?:string, since?:string, until?:string, period?:'current', events?:'true'|'false', limit?:int, starting_after?:string} $query
     * @return array{object:mixed, subject_type:'user'|'org', subject_id:string, since?:int|null, until?:int|null, total:int|float, by_feature:list<array{feature:string|null, total:int|float, events:int}>, events?:array{object?:mixed, data?:list<array{object?:mixed, id?:string, feature?:string|null, quantity?:int|float, source?:'report'|'batch'|'consume'|'refund', idempotency_key?:string, subscription_id?:string|null, ref_key?:string|null, reported_at?:int}>, has_more?:bool, next_cursor?:string|null}}
     */
    public function getUsage(array $query = []): array
    {
        $r = $this->http->request('GET', '/v1/billing/usage', query: $query);

        return is_array($r) ? $r : [];
    }

    /**
     * Every item of `getUsage` across all pages (cursor pagination), one at a time.
     *
     * @param array{subject_type?:'user'|'org', subject_id?:string, feature?:string, since?:string, until?:string, period?:'current', events?:'true'|'false', limit?:int, starting_after?:string} $query
     * @return \Generator<int,mixed>
     */
    public function getUsageAll(array $query = []): \Generator
    {
        return \Atlas\Pagination::iterate(fn (array $q): array => $this->getUsage($q), $query);
    }

    /**
     * Report up to 100 usage events in one call. Each event is its own idempotent report with the fields of POST /v1/billing/usage, so a retried batch records only what is missing. The batch is not all-or-nothing: each result says `recorded`, `duplicate` or `failed` (with the error). The response is 200 whenever the batch itself was well formed.
     *
     * `POST /v1/billing/usage/batch` (scope `billing:write`)
     *
     * @param array{events:list<array{subject_type:'user'|'org', subject_id:string, quantity:int|float, idempotency_key:string, feature?:string, subscription_id?:string}>} $body
     * @param string|null $idempotencyKey sent as `Idempotency-Key`; a retry with the same key replays the first response
     * @return array{object:mixed, recorded:int, duplicates:int, failed:int, results:list<array{index:int, idempotency_key?:string|null, status:'recorded'|'duplicate'|'failed', recorded?:bool, metered?:bool, total?:int|float, error?:array{code?:string, message?:string, param?:string}}>}
     */
    public function batchUsage(array $body, ?string $idempotencyKey = null): array
    {
        $r = $this->http->request('POST', '/v1/billing/usage/batch', body: $body, idempotencyKey: $idempotencyKey);

        return is_array($r) ? $r : [];
    }
